def cases():
    out = []
    for i, (tool, desc, args, destructive, exfil, ambiguous) in enumerate(CASES):
        out.append({
            "id": f"precall-{i:03d}",
            "dataset": "precall",
            "state": {"tool": {"name": tool, "description": desc}, "arguments": args},
            "labels": {"destructive": destructive, "exfiltration": exfil, "dangerous": int(destructive or exfil)},
            "ambiguous": ambiguous,
        })
    return out
